// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        uint256 initialFunding = 100 ether;
        vm.assume(amount <= initialFunding);
        vm.assume(target != address(c));
        vm.assume(target != address(0));

        address funder = makeAddr("funder");
        vm.deal(funder, initialFunding);
        vm.prank(funder);
        (bool sent,) = address(c).call{value: initialFunding}("");
        require(sent, "funding failed");

        uint256 balanceBefore = address(c).balance;

        address actor = makeAddr("nonOwner");
        vm.assume(actor != c.owner());
        vm.assume(actor != funder);

        vm.prank(actor);
        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertEq(address(c).balance, balanceBefore, "non-owner should not change balance via sendMoney");
    }
}
